'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state, view='planner', selectedDay='', period=1, toastTimer, filterTimer, recommendationResults=[];
let upcomingData=null, upcomingError='', upcomingRequest=0, weekOffset=0, weekCount=1, upcomingTruck='', upcomingOperation='';
const filters={plate:'',loading:'',unloading:'',operation:'',status:''};
const names={planner:'Daily planning',upcoming:'Upcoming planning',matches:'Find next load',analytics:'Analytics',trailers:'Trailers',trucks:'Tractors',drivers:'Drivers & carriers',locations:'Saved locations',settings:'Settings & backup'};
const localParts = value => value ? String(value).slice(0,16) : '';
const dayOf = value => value ? String(value).slice(0,10) : '';
const addDays=(day,n)=>new Date(Date.parse(day+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
const formatDay=(day,full=false)=>new Intl.DateTimeFormat('en-GB',{weekday:full?'long':'short',day:'numeric',month:full?'long':'short',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'));
const formatTime=value=>value?new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'}).format(new Date(value)):'—';
const formatDate=value=>value?formatDay(dayOf(value))+' · '+formatTime(value):'—';
const hours=value=>Number(value).toLocaleString('en-GB',{maximumFractionDigits:1})+' h';
const km=value=>value==null?'Unknown':Number(value).toLocaleString('en-GB',{maximumFractionDigits:1})+' km';
const getLocation=id=>state.locations.find(x=>x.id===Number(id));
const placeLabel=p=>p?`${p.city} · ${p.company} · ${p.postal_code}, ${p.country}`:'Unknown location';
const locationHtml=id=>{const p=getLocation(id);return p?`<div class="place"><strong>${esc(p.city)} <span class="muted">${esc(p.postal_code)}</span></strong><small>${esc(p.company)} · ${esc(p.country)}</small></div>`:'—';};
const badge=(value,kind='')=>`<span class="badge ${kind}">${esc(value)}</span>`;
const errorBox='<div class="form-error" role="alert"></div>';
const options=(items,value,label,empty='Choose…')=>`<option value="">${esc(empty)}</option>`+items.map(item=>`<option value="${item.id}" ${Number(value)===item.id?'selected':''}>${esc(label(item))}</option>`).join('');
const field=(label,name,value='',type='text',attrs='',hint='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</div>`;
const selectField=(label,name,body)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${body}</select></div>`;
const notice=(message,warning=false)=>`<div class="notice ${warning?'warning':''}">${message}</div>`;
const empty=(title,message,action='',label='')=>`<div class="empty"><div class="empty-symbol">▦</div><h3>${title}</h3><div>${message}</div>${action?`<button class="btn primary" data-action="${action}">${label}</button>`:''}</div>`;

function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',6500);}
async function api(path,data){const response=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':state.token}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok){const error=new Error(result.error||'Request failed');error.status=response.status;throw error;}return result;}
async function refresh(){state=await api('/api/state');if(!selectedDay)selectedDay=dayOf(state.now);$('#today-label').textContent=formatDay(dayOf(state.now),true);$('#nav-count').textContent=state.orders.filter(x=>x.status==='Planned').length;render();if(view==='upcoming')await loadUpcoming();}
function navigate(next){view=next;render();$('#main').focus();if(next==='upcoming')loadUpcoming();}
function heading(title,subtitle,action='',label=''){return `<div class="heading"><div><div class="eyebrow">MALCOMTRANS / OPERATIONS</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action?`<div class="actions"><button class="btn primary" data-action="${action}">＋ ${label}</button></div>`:''}</div>`;}
function render(){for(const el of document.querySelectorAll('.nav'))el.classList.toggle('active',el.dataset.view===view);$('#breadcrumb').textContent=names[view];$('#main').innerHTML=view==='planner'?plannerView():view==='upcoming'?upcomingView():view==='matches'?matchesView():view==='settings'?settingsView():view==='analytics'?analyticsView():directoryView();}

async function loadUpcoming(){const request=++upcomingRequest,offset=weekOffset,count=weekCount;upcomingData=null;upcomingError='';if(view==='upcoming')render();try{let result;try{result=await api('/api/upcoming',{week_offset:offset,week_count:count});}catch(error){if(error.status!==404)throw error;const current=await api('/api/state');result=weeklyClientAvailability(current,offset,count);if(request===upcomingRequest)state=current;}if(request===upcomingRequest){upcomingData=result;state.now=result.now;if(view==='upcoming')render();}}catch(error){if(request===upcomingRequest){upcomingError=error.message;if(view==='upcoming')render();}}}
function weekStart(day){const weekday=new Date(day+'T12:00:00Z').getUTCDay();return addDays(day,-((weekday+6)%7));}
// Compatibility for an already-running server without the new read-only endpoint.
function dispatchParts(ms){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(ms)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));}
function dispatchMidnight(day){const desired=Date.parse(day+'T00:00:00Z');let instant=desired;for(let i=0;i<3;i++){const p=dispatchParts(instant);const wall=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);instant+=desired-wall;}return instant;}
function dispatchStamp(ms){const p=dispatchParts(ms),wall=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute),offset=Math.round((wall-ms)/60000),pad=n=>String(n).padStart(2,'0');return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}${offset<0?'-':'+'}${pad(Math.floor(Math.abs(offset)/60))}:${pad(Math.abs(offset)%60)}`;}
function weeklyClientAvailability(current,offset,count){if(![0,1,2].includes(offset)||![1,2].includes(count)||offset+count>3)throw new Error('Choose one or two weeks, up to two weeks ahead.');const now=Date.parse(current.now),startDay=addDays(weekStart(dayOf(current.now)),offset*7),horizonStart=dispatchMidnight(startDay),horizonEnd=dispatchMidnight(addDays(startDay,count*7));const orders=current.orders.filter(o=>o.status!=='Cancelled'),trucks=current.trucks.filter(t=>t.active),locations=new Map(current.locations.map(l=>[l.id,l])),drivers=new Map(current.drivers.map(d=>[d.id,d]));const allWindows=[],unknown=[];
  for(const truck of trucks){const own=orders.filter(o=>o.truck_id===truck.id),latest=[...own].sort((a,b)=>Date.parse(b.pickup_at)-Date.parse(a.pickup_at))[0],driver=drivers.get(truck.driver_id||latest?.driver_id),trailer=truck.trailer||latest?.trailer||'';const related=own;const bookings=related.map(o=>[Date.parse(o.pickup_at),Date.parse(o.available_at)]).sort((a,b)=>a[0]-b[0]);let anchors=own.map(o=>({at:Date.parse(o.available_at),location_id:o.unloading_id,source_order_id:o.id,source:o.number}));if(truck.location_id&&truck.available_from)anchors.push({at:Date.parse(truck.available_from),location_id:truck.location_id,source_order_id:null,source:'Reported fleet location'});anchors=anchors.filter(a=>locations.has(a.location_id)).sort((a,b)=>a.at-b.at);if(!anchors.length){unknown.push({truck_id:truck.id,plate:truck.plate,reason:'Add a known location and availability time, or a loading order.'});continue;}
    for(let i=0;i<anchors.length;i++){const anchor=anchors[i],start=Math.max(anchor.at,now,horizonStart),end=Math.min(anchors[i+1]?.at??horizonEnd,horizonEnd);if(start>=end)continue;let cursor=start;const gaps=[];for(const [busyStart,busyEnd] of bookings){if(busyEnd<=cursor||busyStart>=end)continue;if(busyStart>cursor)gaps.push([cursor,Math.min(busyStart,end)]);cursor=Math.max(cursor,busyEnd);if(cursor>=end)break;}if(cursor<end)gaps.push([cursor,end]);for(const [from,until] of gaps){if(until-from<7200000)continue;const next=related.find(o=>Date.parse(o.pickup_at)===until);allWindows.push({truck_id:truck.id,plate:truck.plate,trailer,driver_id:driver?.id??null,driver_name:driver?.name||'Driver not assigned',carrier:driver?.carrier||'',operation:truck.operation,location:locations.get(anchor.location_id),source:anchor.source,source_order_id:anchor.source_order_id,known_since:dispatchStamp(anchor.at),from:dispatchStamp(from),until:dispatchStamp(until),next_order:next?.number??null});}}
  }
  const weeks=[];for(let i=0;i<count;i++){const day=addDays(startDay,i*7),weekStartMs=dispatchMidnight(day),weekEndMs=dispatchMidnight(addDays(day,7)),windows=[];for(const window of allWindows){const from=Math.max(Date.parse(window.from),weekStartMs),until=Math.min(Date.parse(window.until),weekEndMs);if(until-from<7200000)continue;windows.push({...window,from:dispatchStamp(from),until:dispatchStamp(until),hours:Math.round((until-from)/360000)/10,week_end_boundary:until===weekEndMs});}windows.sort((a,b)=>Date.parse(a.from)-Date.parse(b.from)||a.plate.localeCompare(b.plate));const available=new Set(windows.map(w=>w.truck_id)),missing=new Set(unknown.map(t=>t.truck_id)),thursday=new Date(day+'T12:00:00Z');thursday.setUTCDate(thursday.getUTCDate()+3);const year=thursday.getUTCFullYear(),yearStart=new Date(Date.UTC(year,0,1,12)),weekNumber=Math.ceil(((thursday-yearStart)/86400000+1)/7);weeks.push({start:day,end:addDays(day,6),week_number:weekNumber,year,windows,scheduled:trucks.filter(t=>!available.has(t.id)&&!missing.has(t.id)).map(t=>({truck_id:t.id,plate:t.plate}))});}
  return {weeks,unknown,active_trucks:trucks.length,now:current.now,week_offset:offset,week_count:count};
}
function upcomingView(){const monday=weekStart(dayOf(state.now));const filtered=window=>(!upcomingTruck||window.truck_id===Number(upcomingTruck))&&(!upcomingOperation||window.operation===upcomingOperation);const weeks=upcomingData?.weeks||[];const windows=weeks.flatMap(w=>w.windows.filter(filtered));const truckIds=new Set(windows.map(w=>w.truck_id));
  return heading('Upcoming planning','Availability by tractor registration. Monday to Sunday, up to two weeks ahead.','new-order','New loading order')+`
  <section class="panel"><div class="upcoming-controls"><div class="field"><label for="upcoming-week">Starting week</label><select id="upcoming-week">${['This week','Next week','In 2 weeks'].map((label,index)=>`<option value="${index}" ${weekOffset===index?'selected':''}>${label} · ${formatDay(addDays(monday,index*7))} – ${formatDay(addDays(monday,index*7+6))}</option>`).join('')}</select></div><div class="field"><label for="upcoming-count">Show</label><select id="upcoming-count"><option value="1" ${weekCount===1?'selected':''}>1 calendar week</option><option value="2" ${weekCount===2?'selected':''} ${weekOffset===2?'disabled':''}>2 consecutive weeks</option></select></div><div class="field"><label for="upcoming-truck">Truck</label><select id="upcoming-truck">${options(state.trucks.filter(t=>t.active),upcomingTruck,t=>t.plate,'All active trucks')}</select></div><div class="field"><label for="upcoming-operation">Operation</label><select id="upcoming-operation"><option value="">All operations</option>${['International','National','Local'].map(value=>`<option ${upcomingOperation===value?'selected':''}>${value}</option>`).join('')}</select></div><button class="btn small" data-action="refresh-upcoming">↻ Refresh</button></div><div class="upcoming-horizon">Planning horizon: this week through ${formatDay(addDays(monday,20))}. Only future free windows of at least 2 hours are shown.</div></section>
  ${upcomingError?`<div class="form-error">${esc(upcomingError)}</div>`:!upcomingData?'<section class="panel loading">Checking weekly availability…</section>':`
  <div class="upcoming-summary"><div><strong>${weeks.length}</strong><span>${weeks.length===1?'week selected':'weeks selected'}</span></div><div><strong>${truckIds.size}</strong><span>trucks with free time</span></div><div><strong>${windows.length}</strong><span>free windows across selected weeks</span></div></div>
  ${weeks.map(week=>{const entries=week.windows.filter(filtered);const unavailable=week.scheduled.filter(t=>(!upcomingTruck||t.truck_id===Number(upcomingTruck))&&(!upcomingOperation||state.trucks.find(truck=>truck.id===t.truck_id)?.operation===upcomingOperation));return `<section class="panel upcoming-week" data-week-start="${week.start}"><div class="panel-head"><div><div class="eyebrow">WEEK ${week.week_number} · ${week.year}</div><h2>${formatDay(week.start)} – ${formatDay(week.end)}</h2><p>${entries.length} free ${entries.length===1?'window':'windows'} · ${new Set(entries.map(w=>w.truck_id)).size} trucks</p></div>${badge('Monday → Sunday','gray')}</div>${entries.length?`<div class="weekly-window-grid">${entries.map((window,index)=>weeklyWindow(window,week,index)).join('')}</div>`:empty('No free windows in this week','There is no known future availability of at least 2 hours for this selection.')}<div class="weekly-footnote">${unavailable.length?`<details><summary>${unavailable.length} trucks without a known free window this week</summary><p>${unavailable.map(t=>esc(t.plate)).join(' · ')}</p><p>They may be booked, become available later, or have gaps shorter than 2 hours.</p></details>`:entries.length?'All trucks with known availability have a free window in this week.':'No confirmed availability for this selection. Check missing details below.'}</div></section>`;}).join('')}
  ${upcomingData.unknown.length?`<section class="panel padded"><details><summary>${upcomingData.unknown.length} active trucks need availability details</summary>${upcomingData.unknown.map(t=>`<p class="subtitle"><strong>${esc(t.plate)}</strong> · ${esc(t.reason)}</p>`).join('')}</details></section>`:''}
  ${notice('Availability follows the orders for each tractor and reported location, not driver assignments or live GPS. Confirm driver hours, rest and positioning before assigning a load. A free window that crosses Sunday is split between the selected weeks.')}`}`;
}
function weeklyWindow(window,week,index){const end=window.week_end_boundary?`Sun ${week.end.slice(8)} · 23:59`:formatDate(window.until);return `<article class="weekly-window"><div class="weekly-window-head"><h3>${esc(window.plate)}</h3>${badge(window.operation,'gray')}</div><p class="weekly-driver">${esc(window.driver_name)} · ${esc(window.carrier)}</p><div class="weekly-location"><span>Available near</span><strong>${esc(window.location.city)}</strong><small>${esc(window.location.company)} · ${esc(window.location.postal_code)}, ${esc(window.location.country)}</small></div><div class="weekly-times"><div><span>FROM</span><strong>${formatDate(window.from)}</strong></div><div><span>${window.week_end_boundary?'THROUGH WEEK END':window.next_order?'UNTIL NEXT BOOKING':'AVAILABLE UNTIL'}</span><strong>${end}</strong></div></div><div class="weekly-source"><strong>${hours(window.hours)} free in this week</strong><p>${window.next_order?'Before '+esc(window.next_order):'No next booking inside this window.'}</p><p>Position: ${esc(window.source)}<br>Known since ${formatDate(window.known_since)}</p></div><button class="btn small" data-action="upcoming-open-day" data-truck="${window.truck_id}" data-date="${dayOf(window.from)}">Open daily plan ↗</button></article>`;}

function filteredOrders(){return state.orders.filter(order=>{
  const pickup=placeLabel(getLocation(order.loading_id)).toLowerCase(),drop=placeLabel(getLocation(order.unloading_id)).toLowerCase();
  return order.plate.toLowerCase().includes(filters.plate.toLowerCase())&&pickup.includes(filters.loading.toLowerCase())&&drop.includes(filters.unloading.toLowerCase())&&(!filters.operation||order.operation===filters.operation)&&(filters.status?order.status===filters.status:order.status!=='Cancelled');
});}
function opportunities(){const endDay=addDays(selectedDay,period-1),list=[];const orders=state.orders.filter(o=>o.status!=='Cancelled');
  for(const order of orders){const truck=state.trucks.find(t=>t.id===order.truck_id);if(!truck?.active)continue;
    const ready=order.available_at;
    const next=orders.filter(o=>o.id!==order.id&&(o.truck_id===order.truck_id||o.driver_id===order.driver_id||(order.trailer&&o.trailer.toLowerCase()===order.trailer.toLowerCase()))&&new Date(o.pickup_at)>=new Date(ready)).sort((a,b)=>new Date(a.pickup_at)-new Date(b.pickup_at))[0];
    const from = new Date(ready)>new Date(state.now)?ready:state.now;
    if(next&&new Date(next.pickup_at)-new Date(from)<2*3600000)continue;
    if(dayOf(from)>endDay|| (next&&dayOf(next.pickup_at)<selectedDay))continue;
    if(filters.plate&&!order.plate.toLowerCase().includes(filters.plate.toLowerCase()))continue;
    if(filters.operation&&order.operation!==filters.operation)continue;
    if(filters.loading||filters.unloading){if(!placeLabel(getLocation(order.unloading_id)).toLowerCase().includes((filters.unloading||filters.loading).toLowerCase()))continue;}
    list.push({order,from,next});
  }
  return list.sort((a,b)=>new Date(a.from)-new Date(b.from));
}
function dailyStopSection(orders,kind){const loading=kind==='Loading',dateIsToday=selectedDay===dayOf(state.now),label=dateIsToday?kind+' today':kind+' · '+formatDay(selectedDay);const rows=[...orders].sort((a,b)=>new Date(loading?a.pickup_at:a.unloading_at)-new Date(loading?b.pickup_at:b.unloading_at));return `<section class="panel daily-stop-section ${loading?'daily-loading':'daily-unloading'}" data-daily-section="${loading?'loading':'unloading'}"><div class="panel-head"><div><h2><span class="daily-stop-icon">${loading?'↗':'↙'}</span> ${label} <span class="section-count">${rows.length} ${rows.length===1?'order':'orders'}</span></h2><p>${loading?'Trucks loading on this date, ordered by loading time.':'Trucks unloading on this date, ordered by estimated unloading time. Availability is shown after unloading.'}</p></div>${badge(loading?'Loading':'Unloading',loading?'':'amber')}</div>${rows.length?`<div class="schedule journey-schedule"><table><thead><tr><th>Truck & driver · ${loading?'loading':'unloading'} time</th><th>Complete journey · loading → unloading</th><th>Available after unloading</th><th>Loading order</th></tr></thead><tbody>${rows.map(order=>journeyRow({order,day:selectedDay,loading,unloading:!loading})).join('')}</tbody></table></div>`:empty(loading?'No loading on this day':'No unloading on this day','No orders match this date and the selected filters.')}</section>`;}
function plannerView(){const orders=filteredOrders(),loading=orders.filter(o=>dayOf(o.pickup_at)===selectedDay),unloading=orders.filter(o=>dayOf(o.unloading_at)===selectedDay),opp=opportunities();const dateLabel=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(selectedDay+'T12:00:00Z')).toUpperCase();
  return heading(dateLabel,'Daily planning · '+formatDay(selectedDay,true)+(selectedDay===dayOf(state.now)?' · Today':''),'new-order','New loading order')+`
  <section class="panel daily-date-panel"><div class="panel-head"><div><h2>Choose your planning day</h2><p>Loading and unloading for one date. All times use the Europe/Madrid dispatch clock.</p></div><div class="actions"><button class="btn small" data-action="prev-day">‹ Previous day</button><input type="date" id="planning-date" value="${selectedDay}" aria-label="Planning date"><button class="btn small" data-action="next-day">Next day ›</button><button class="btn primary small" data-action="today">Today</button></div></div>
  <div class="filters"><div class="filter"><label for="filter-plate">Tractor registration</label><input id="filter-plate" data-filter="plate" placeholder="Search registration" value="${esc(filters.plate)}"></div><div class="filter wide"><label for="filter-loading">Loading place</label><input id="filter-loading" data-filter="loading" placeholder="City, company or postcode" value="${esc(filters.loading)}"></div><div class="filter wide"><label for="filter-unloading">Unloading place</label><input id="filter-unloading" data-filter="unloading" placeholder="City, company or postcode" value="${esc(filters.unloading)}"></div><div class="filter"><label for="filter-operation">Operation</label><select id="filter-operation" data-filter="operation"><option value="">All operations</option>${['International','National','Local'].map(v=>`<option ${filters.operation===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="filter"><label for="filter-status">Order status</label><select id="filter-status" data-filter="status"><option value="">All active</option>${['Planned','Completed','Cancelled'].map(v=>`<option ${filters.status===v?'selected':''}>${v}</option>`).join('')}</select></div><button class="btn small" data-action="clear-filters">Reset</button></div>
  </section>
  <div class="stats daily-stats"><div class="stat"><div class="stat-top">Loading on this day<span class="stat-icon">↗</span></div><strong>${loading.length}</strong><small>Ordered by loading time</small></div><div class="stat"><div class="stat-top">Unloading on this day<span class="stat-icon">↙</span></div><strong>${unloading.length}</strong><small>Ordered by estimated unloading time</small></div><div class="stat"><div class="stat-top">Reload opportunities<span class="stat-icon">⌁</span></div><strong>${opp.length}</strong><small class="positive">Free windows for the selected day</small></div></div>
  ${dailyStopSection(loading,'Loading')}
  ${dailyStopSection(unloading,'Unloading')}
  <section class="panel"><div class="panel-head"><div><h2>Daily reload windows <span class="section-count">${opp.length} windows</span></h2><p>Planned availability after unloading. A driving break or rest may still be needed before the next trip.</p></div><button class="btn small" data-view="upcoming">Open weekly planning →</button></div>${opp.length?`<div class="alert-grid">${opp.slice(0,12).map(({order,from,next})=>`<article class="opportunity"><h3>${esc(order.plate)} ${badge(order.operation,'gray')}</h3><p><strong>${esc(getLocation(order.unloading_id)?.city)}</strong> · ${esc(getLocation(order.unloading_id)?.company)}</p><p>${esc(order.driver_name)} · Ready ${formatDate(from)}<br>${next?'Until '+formatDate(next.pickup_at):'No next loading assigned'}</p><button class="link-button" data-action="reload-order" data-id="${order.id}">Plan next loading ↗</button></article>`).join('')}</div>`:empty('No open reload windows','Add a loading order to see when a truck becomes available after unloading.')}</section>`;
}
function journeyStop(id,at,kind,active){const point=getLocation(id);return `<div class="journey-stop ${kind==='Loading'?'loading-stop':'unloading-stop'} ${active?'active-stop':'context-stop'}"><div class="stop-label">${kind==='Loading'?'↗':'↙'} ${kind}${active?'<span>THIS DAY</span>':''}</div><strong>${esc(point?.city||'Unknown location')}</strong><div class="stop-company">${esc(point?.company)}</div><div class="stop-address">${esc(point?.postal_code)} · ${esc(point?.country)}</div><div class="stop-time">${active?formatTime(at):formatDate(at)}${kind==='Unloading'?'<span>estimated</span>':''}</div></div>`;}
function completedTripsOnDay(truckId,day){return state.orders.filter(order=>order.truck_id===truckId&&order.status==='Completed'&&dayOf(order.unloading_at)===day).length;}
function tripProgressBadge(order,day){const count=completedTripsOnDay(order.truck_id,day),done=count>=4,label=`${order.plate}: ${count} completed trips out of a daily target of 4 on ${formatDay(day,true)}. Counts completed orders by unloading date, across all locations.`;return `<div class="journey-progress"><span class="daily-trip-progress ${done?'target-reached':'target-pending'}" title="${esc(label)}" aria-label="${esc(label)}">${done?'✓':'◷'} ${count} / 4 trips</span></div>`;}
function journeyRow({order:o,day,loading,unloading}){return `<tr class="journey-row" data-order-id="${o.id}" data-planning-day="${day}"><td class="vehicle-cell"><strong>${esc(o.plate)}</strong><small>Trailer ${esc(o.trailer||'not assigned')}</small><div class="journey-driver">${esc(o.driver_name)}</div><small>${esc(o.carrier)}</small><small>${badge(o.operation,'gray')}</small><div class="vehicle-activity">${loading?`<div class="activity-label loading-activity">↗ Loading <b>${formatTime(o.pickup_at)}</b></div>`:''}${unloading?`<div class="activity-label unloading-activity">↙ Unloading <b>≈ ${formatTime(o.unloading_at)}</b></div>`:''}<small>${loading&&unloading?'Both stops on this day':loading?'Unloading '+formatDay(dayOf(o.unloading_at)):'Loading '+formatDay(dayOf(o.pickup_at))}</small></div></td><td class="journey-cell">${tripProgressBadge(o,day)}<div class="journey-stops">${journeyStop(o.loading_id,o.pickup_at,'Loading',loading)}<div class="journey-connector"><span>→</span><small>${km(o.distance_km)}</small></div>${journeyStop(o.unloading_id,o.unloading_at,'Unloading',unloading)}</div></td><td class="ready-cell"><div class="ready-label">${o.status==='Cancelled'?'Cancelled order':'Planned availability'}</div><strong>${formatDate(o.available_at)}</strong><small>At ${esc(getLocation(o.unloading_id)?.city)}</small>${o.status!=='Cancelled'?'<small>Check remaining driver hours</small>':''}</td><td class="order-cell"><button class="link-button" data-action="order-detail" data-id="${o.id}">${esc(o.number)}</button><small>${badge(o.status,o.status==='Cancelled'?'gray':o.status==='Completed'?'blue':'')}</small><button class="journey-open" data-action="order-detail" data-id="${o.id}">View journey ↗</button></td></tr>`;}

function directoryView(){const type=view,items=state[type];let body='';
  if(type==='drivers')body=items.map(d=>`<article class="directory-card"><h3>${esc(d.name)}</h3>${badge(d.active?'Active':'Inactive',d.active?'':'gray')}<p>${esc(d.carrier)}<br>${esc(d.phone||'No phone number')}<br>DNI / NIE: ${esc(d.dni_nie||'Not provided')}<br>${state.trucks.filter(t=>t.driver_id===d.id).map(t=>esc(t.plate)).join(', ')||'No default truck'}</p><div class="actions"><button class="btn small" data-action="edit-driver" data-id="${d.id}">Edit driver</button></div></article>`).join('');
  if(type==='trucks')body=items.map(t=>`<article class="directory-card"><div class="actions"><h3>${esc(t.plate)}</h3>${badge(t.operation)}</div><p>Trailer <strong>${esc(t.trailer||'Not assigned')}</strong><br>Driver: ${esc(state.drivers.find(d=>d.id===t.driver_id)?.name||'Not assigned')}<br>Last reported base: ${esc(getLocation(t.location_id)?.city||'Not set')}<br>${t.available_from?'Base available: '+formatDate(t.available_from):'Base availability not set'}<br>${t.height} m high · ${t.length} m long · ${t.weight/1000} t gross</p><div class="actions">${badge(t.active?'Active':'Inactive',t.active?'':'gray')}<button class="btn small" data-action="edit-truck" data-id="${t.id}">Edit & assign</button></div></article>`).join('');
  if(type==='trailers')body=items.map(t=>`<article class="directory-card"><h3>${esc(t.plate)}</h3>${badge(t.active?'Active':'Inactive',t.active?'':'gray')}<p>${esc(t.notes||'No notes')}<br>Default for: ${state.trucks.filter(truck=>truck.trailer_id===t.id).map(truck=>esc(truck.plate)).join(', ')||'No tractor assigned'}</p><button class="btn small" data-action="edit-trailer" data-id="${t.id}">Edit trailer</button></article>`).join('');
  if(type==='locations')body=items.map(p=>`<article class="directory-card"><h3>${esc(p.city)}</h3>${badge(p.country,'gray')}<p><strong>${esc(p.company)}</strong><br>${esc(p.postal_code)} · ${esc(p.address||'Address not provided')}<br>${p.lat!=null?`Coordinates: ${p.lat}, ${p.lon}`:'Coordinates not set — manual routing available'}</p><div class="actions"><button class="btn small" data-action="edit-location" data-id="${p.id}">Edit location</button><button class="link-button" data-action="match-location" data-id="${p.id}">Find nearby truck ↗</button></div></article>`).join('');
  const singular={drivers:'driver',trucks:'truck',trailers:'trailer',locations:'location'}[type];
  const sub={drivers:'Your drivers and partner carriers. Assign a default driver to each tractor.',trailers:'Registered trailers with separate plates. Select a saved trailer when assigning a tractor or trip.',trucks:'Tractor registrations, trailer assignments and truck profiles for routing.',locations:'Plain-text city and company names, with postcodes and optional verified coordinates.'}[type];
  return heading(names[type],sub,'new-'+singular,'Add '+singular)+`<div class="search-row"><input id="directory-search" type="search" placeholder="Search ${type}…" aria-label="Search ${type}"><span class="badge gray">${items.length} saved</span></div><div class="directory-cards">${body||`<div class="panel span-2">${empty('Your '+type+' will appear here','Add your first '+singular+' to start building the planning.','new-'+singular,'Add '+singular)}</div>`}</div>`;
}
function matchesView(preselect=''){return heading('Find next load','Match a new loading point with the nearest planned unloading or known truck location.')+`<div class="split"><section class="panel padded"><h2>New loading opportunity</h2><form id="match-form">${errorBox}${selectField('Loading location','location_id',options(state.locations,preselect,placeLabel))}<button class="link-button" type="button" data-action="new-location">＋ Add a new location</button><div class="field"></div>${field('Loading date & time','pickup_at',(selectedDay<=dayOf(state.now)?addDays(dayOf(state.now),1):selectedDay)+'T08:00','datetime-local','required')}<label class="checkbox"><input name="use_here" type="checkbox" ${state.here_configured?'':'disabled'}><span>Check truck-road distance and arrival with HERE${state.here_configured?'':' (configure API key first)'}</span></label>${notice('Without HERE, ranking uses straight-line distance or the same postal area. This is a shortlist, not confirmation that the truck can reach the load.')}<button class="btn primary" type="submit">⌁ Find closest trucks</button></form></section><section class="panel"><div class="panel-head"><div><h2>Suggested trucks</h2><p>Closest planned positions, with availability checked against assigned jobs.</p></div></div><div id="match-results">${empty('A better place for the next load','Choose a loading location and time to find nearby trucks.')}</div></section></div>`;}
function settingsView(){return heading('Settings & backup','Routing connections, planning assumptions and a safe copy of your dispatch data.')+`<div class="settings-grid"><section class="panel padded"><h3>Truck routing · HERE</h3>${badge(state.here_configured?'API key configured':'Not configured',state.here_configured?'':'amber')}<p>Manual kilometres and driving hours work without an account. Automatic routes use HERE truck mode and the vehicle height, width, length and gross weight saved under Trucks.</p><p>To connect HERE, close the server and run in PowerShell:</p><code class="code">$env:HERE_API_KEY = 'your-key-here'\npython app.py</code><p>The key stays on the server, loaded from the environment or local configuration. Give the account access to Geocoding & Search and Routing. API requests send the selected coordinates, addresses and vehicle profile to HERE and may incur provider charges.</p><p><a href="https://docs.here.com/routing/docs/routing-v8-truck-routing" target="_blank" rel="noreferrer">HERE truck routing documentation ↗</a></p><h3>Location accuracy</h3><p>Confirm the geocoded result before saving. A city/postcode coordinate can represent the area, not the exact truck entrance. Add a street address or verified entrance coordinates for better routing.</p></section>
<section class="panel padded"><h3>Database backup</h3><p>Your fleet, locations and loading orders are stored in <strong>data/malcomtrans.sqlite3</strong>. This button creates a consistent SQLite backup while the app is running.</p><a class="btn primary" href="/api/backup" download>↓ Download database backup</a><p>To restore: stop the server, keep a copy of the current database, replace data/malcomtrans.sqlite3 with the backup, then restart.</p><h3>Local access</h3><p>This app listens on 127.0.0.1. Anyone with access to this computer can use its local data. It has no multi-user sign-in or live tracking.</p><h3>Project folder</h3><p>The project is inside an existing Python virtual environment. Back it up before recreating or deleting that environment.</p></section>
<section class="panel padded span-2"><h3>Single-driver EU planning model</h3><ul><li>9 hours driving per daily period; 45-minute break after 4.5 hours, or daily rest when due.</li><li>11-hour daily rest; a conservative 13-hour duty window includes loading and unloading.</li><li>56 hours in an ISO calendar week and 90 hours across two adjacent weeks; regular weekly rest of at least 45 hours, due no later than the supplied weekly-rest deadline.</li><li>Enter actual driving, duty and weekly hours at the loading appointment. “Carry forward” reuses previous planned orders. Unassigned gaps are assumed to be rest or breaks; confirm this against the tachograph.</li><li>10-hour extensions, reduced/split rests, multi-manning, compensation, working-time averaging, country/holiday driving bans, ferries and exceptional derogations are not modelled.</li><li>All displayed and entered times use one dispatch clock: Europe/Madrid, including daylight saving. Convert foreign local appointment times to this clock.</li><li>Route times, availability alerts and reload recommendations are planning estimates. They cannot certify compliance or replace driver confirmation and tachograph records.</li></ul><a href="https://transport.ec.europa.eu/transport-modes/road/social-provisions/driving-time-and-rest-periods_en" target="_blank" rel="noreferrer">European Commission: driving time and rest periods ↗</a></section></div>`;}

function showModal(title,content,kicker='DISPATCH WORKSPACE'){const modal=$('#modal');$('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=content;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function showError(form,error){const el=$('.form-error',form);if(el){el.textContent=error.message;el.scrollIntoView({block:'nearest'});}else toast(error.message,true);}
function formObject(form){const obj=Object.fromEntries(new FormData(form));for(const input of form.querySelectorAll('input[type=checkbox]'))obj[input.name]=input.checked;return obj;}
function openMaster(type,id=null,returnTo=null){const item=state[type].find(x=>x.id===Number(id))||{};const singular={drivers:'driver',trucks:'truck',trailers:'trailer',locations:'location'}[type];let fields='';
  if(type==='drivers')fields=field('Driver name','name',item.name||'','text','required maxlength="200"')+field('DNI / NIE (optional)','dni_nie',item.dni_nie||'','text','maxlength="30" autocomplete="off"')+field('Phone','phone',item.phone||'','tel','maxlength="60"')+field('Carrier / company','carrier',item.carrier||'MalcomTrans','text','maxlength="200"');
  if(type==='trucks')fields=field('Tractor registration','plate',item.plate||'','text','required maxlength="30"')+trailerPicker('Assigned trailer',item.trailer_id,item.trailer)+selectField('Default driver','driver_id',options(state.drivers.filter(d=>d.active||d.id===item.driver_id),item.driver_id,d=>d.name+' · '+d.carrier,'Assign later'))+selectField('Operation','operation',['International','National','Local'].map(v=>`<option ${v===(item.operation||'International')?'selected':''}>${v}</option>`).join(''))+selectField('Known base / current reported location','location_id',options(state.locations,item.location_id,placeLabel,'Not set'))+field('Available at this location','available_from',localParts(item.available_from),'datetime-local','', 'Used only when there is no preceding planned unloading.')+`<div class="span-2 section-title">Full combination profile · tractor + trailer</div>`+field('Height (metres)','height',item.height??4,'number','step="0.01" min="0.5" max="6" required')+field('Width (metres)','width',item.width??2.55,'number','step="0.01" min="0.5" max="4" required')+field('Length (metres)','length',item.length??16.5,'number','step="0.01" min="2" max="30" required')+field('Gross / conservative laden weight (kg)','weight',item.weight??40000,'number','step="1" min="1000" max="100000" required');
  if(type==='trailers')fields=field('Trailer registration','plate',item.plate||'','text','required maxlength="30"')+field('Notes (optional)','notes',item.notes||'','text','maxlength="2000"');
  if(type==='locations')fields=field('Company / loading or unloading site','company',item.company||'','text','required maxlength="200"')+field('City','city',item.city||'','text','required maxlength="200"')+field('Postal code','postal_code',item.postal_code||'','text','required maxlength="200"')+field('Country','country',item.country||'','text','required maxlength="200" placeholder="e.g. Spain"')+`<div class="span-2">${field('Street address / site entrance (optional)','address',item.address||'','text','maxlength="200"')}<button class="btn small" type="button" data-action="geocode" ${state.here_configured?'':'disabled'}>⌖ Find address with HERE</button>${!state.here_configured?'<p class="subtitle">You can save plain text now. Coordinates can be added manually or later with HERE.</p>':''}</div><div class="geocode-results" id="geocode-results"></div>`+field('Latitude (optional)','lat',item.lat??'','number','step="any" min="-90" max="90"')+field('Longitude (optional)','lon',item.lon??'','number','step="any" min="-180" max="180"')+`<input name="geo_label" type="hidden" value="${esc(item.geo_label||'')}"><div class="span-2">${notice('Plain-text city and company names are preserved as entered. Confirm coordinates before routing. Referenced locations retain their original address to preserve loading-order history.')}</div>`;
  const content=`<form id="master-form" data-type="${type}">${errorBox}<input name="id" type="hidden" value="${item.id||''}"><div class="form-grid">${fields}</div>${type!=='locations'?`<label class="checkbox"><input type="checkbox" name="active" ${item.active!==0?'checked':''}>Active ${singular}</label>`:''}<div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">Save ${singular}</button></div></form>`;
  showModal((id?'Edit ':'Add ')+singular,content);$('#master-form')._returnTo=returnTo;
}

const clockDefaults={drive_today:0,drive_since_break:0,duty_today:0,drive_week:0,drive_previous_week:0,weekly_rest_due_in:144};
const locationSignature=point=>['address','postal_code','city','country','company'].map(key=>point[key]||'').join('|');
const hasCoordinates=point=>point&&point.lat!=null&&point.lon!=null&&point.lat!==''&&point.lon!==''&&Number.isFinite(Number(point.lat))&&Number.isFinite(Number(point.lon));
function orderGeoBox(form,slot){const box=form.querySelector('[data-order-geo="'+slot+'"]');if(!box)return;const point=getLocation(form.elements[slot].value),job=form._geoJobs?.[slot];if(form.elements.route_mode.value!=='here'||!point){box.innerHTML='';return;}if(hasCoordinates(point)){box.innerHTML=`<div class="geo-confirmed">✓ Coordinates saved <span>${esc(point.geo_label||[point.address,point.postal_code,point.city,point.country].filter(Boolean).join(', '))}</span></div>`;return;}const label=slot==='loading_id'?'Loading':'Unloading',query=job?.id===point.id?job.query:[point.address,point.postal_code,point.city,point.country].filter(Boolean).join(', ');box.innerHTML=`<div class="order-geo-box"><strong>⌖ Confirm ${label.toLowerCase()} address</strong><p>${job?.status==='loading'?'Finding coordinates with HERE…':'Select the correct address below. Coordinates will be saved with this location.'}</p>${!point.address?'<p class="geo-area-warning">No street address is saved. A postal code may identify an area; refine the search to the site entrance.</p>':''}<label class="geo-search-label" for="order-query-${slot}">Address search</label><div class="inline-actions"><input id="order-query-${slot}" value="${esc(query)}" maxlength="600" aria-label="${label} address search"><button type="button" class="btn small" data-action="search-order-location" data-slot="${slot}" ${job?.status==='loading'?'disabled':''}>Search</button></div>${job?.error?`<div class="geo-inline-error">${esc(job.error)}</div>`:''}${job?.matches?.map((match,index)=>`<button type="button" class="geo-option" data-action="confirm-order-location" data-slot="${slot}" data-index="${index}"><strong>Confirm this address →</strong><span>${esc(match.label)}</span><small>${esc(match.result_type)} · ${match.lat}, ${match.lon}${['locality','administrativeArea','postalCode'].includes(match.result_type)?' · Area-level match — verify site entrance':''}</small></button>`).join('')||''}${job?.status==='ready'&&!job.matches.length?'<p>No matches. Add a street address and country, then search again.</p>':''}</div>`;}
async function searchOrderLocation(form,slot,queryOverride=null){const point=getLocation(form.elements[slot].value);if(!point||hasCoordinates(point))return;form._geoJobs??={};const signature=locationSignature(point),existing=form._geoJobs[slot];if(queryOverride===null&&existing?.id===point.id&&existing.signature===signature){orderGeoBox(form,slot);return existing.promise;}const query=queryOverride??[point.address,point.postal_code,point.city,point.country].filter(Boolean).join(', '),job={id:point.id,signature,query,status:'loading',matches:[],error:''};form._geoJobs[slot]=job;orderGeoBox(form,slot);job.promise=(async()=>{try{const response=await api('/api/geocode',{query});job.matches=response.matches;job.status='ready';}catch(error){job.error=error.message;job.status='error';}if(form.isConnected&&form._geoJobs[slot]===job)orderGeoBox(form,slot);})();return job.promise;}
async function ensureOrderCoordinates(form,search=false){if(form.elements.route_mode.value!=='here')return true;const slots=['loading_id','unloading_id'];for(const slot of slots)orderGeoBox(form,slot);if(search)await Promise.all(slots.map(slot=>searchOrderLocation(form,slot)));return slots.every(slot=>hasCoordinates(getLocation(form.elements[slot].value)));}
async function confirmOrderLocation(form,slot,index){const job=form._geoJobs?.[slot],point=getLocation(form.elements[slot].value),match=job?.matches[index];if(!point||!match||job.id!==point.id||job.signature!==locationSignature(point))throw new Error('The selected location changed. Search again before confirming.');const latestState=await api('/api/state'),latest=latestState.locations.find(p=>p.id===point.id);if(!latest||locationSignature(latest)!==job.signature)throw new Error('This address was edited elsewhere. Refresh the location list before confirming coordinates.');await api('/api/locations',{...latest,lat:match.lat,lon:match.lon,geo_label:match.label});state.locations=state.locations.map(p=>p.id===point.id?{...latest,lat:match.lat,lon:match.lon,geo_label:match.label}:p);await ensureOrderCoordinates(form,false);toast('Address confirmed. Coordinates saved for future orders.');}
function orderData(form){const data=formObject(form);data.clock={};for(const key of Object.keys(clockDefaults)){data.clock[key]=Number(data['clock_'+key]);delete data['clock_'+key];}if(data.id)data.id=Number(data.id);else delete data.id;return data;}
function dispatchInputInstant(value){if(/[zZ]$|[+-]\d{2}:\d{2}$/.test(value))return Date.parse(value);const wanted=Date.parse(value.slice(0,16)+':00Z');let guess=wanted;for(let i=0;i<3;i++){const p=dispatchParts(guess);guess+=wanted-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);}return guess;}
function loadingRestSuggestion(data,creditFrom=null){const clock=data.clock||{},loading=Number(data.loading_hours??1),duty=Number(clock.duty_today||0),due=Number(clock.weekly_rest_due_in??144);if(!data.pickup_at||!Number.isFinite(loading)||loading<=0||(!Number.isFinite(duty))||(!Number.isFinite(due)))return null;const at=dispatchInputInstant(data.pickup_at),deadline=at+due*3600000;if(duty+loading<=13+0.00001&&at+loading*3600000<=deadline)return null;const restStart=creditFrom?Math.min(at,Date.parse(creditFrom)):at;let weekly=at+loading*3600000>deadline;let end=Math.max(at,restStart+11*3600000);if(end+loading*3600000>deadline)weekly=true;if(weekly)end=Math.max(at,restStart+45*3600000);const oldWeek=weekStart(dispatchStamp(at).slice(0,10)),newWeek=weekStart(dispatchStamp(end).slice(0,10)),weeks=Math.round((Date.parse(newWeek+'T00:00Z')-Date.parse(oldWeek+'T00:00Z'))/604800000);const nextClock={...clock,drive_today:0,drive_since_break:0,duty_today:0,drive_week:weeks>0?0:Number(clock.drive_week||0),drive_previous_week:weeks>1?0:weeks===1?Number(clock.drive_week||0):Number(clock.drive_previous_week||0),weekly_rest_due_in:weekly?144:Math.max(0,(deadline-end)/3600000)};return {pickup_at:dispatchStamp(end),clock:nextClock,rest_hours:weekly?45:11,remaining_hours:Math.max(0,(end-at)/3600000),credited:!!creditFrom,original_at:dispatchStamp(at)};}
function renderLoadingRestSuggestion(form){const data=orderData(form),suggestion=loadingRestSuggestion(data,form._restCreditFrom);form._restSuggestion=suggestion;const box=$('#rest-suggestion',form);if(!suggestion){box.innerHTML='';return false;}box.innerHTML=notice(`<strong>The truck is free, but driver rest is needed before loading.</strong><br>Proposed loading: <strong>${formatDate(suggestion.pickup_at)}</strong> after ${suggestion.rest_hours} hours of ${suggestion.rest_hours===45?'weekly':'daily'} rest.${suggestion.credited?' The unassigned gap after the previous job counts toward this rest only if the driver actually rests.':' This proposal assumes uninterrupted rest from the selected time.'}<br><button type="button" class="btn small" data-action="apply-rest-suggestion">Use suggested loading time →</button>`,true);return true;}
async function carryOrderClock(form){const data=orderData(form),response=await api('/api/clock',data);if(!form.isConnected||form.elements.pickup_at.value!==data.pickup_at||String(form.elements.driver_id.value)!==String(data.driver_id))return;fillClock(response);const at=dispatchInputInstant(data.pickup_at),prior=state.orders.filter(o=>o.driver_id===Number(data.driver_id)&&o.status!=='Cancelled'&&o.id!==data.id&&Date.parse(o.available_at)<=at).sort((a,b)=>Date.parse(b.available_at)-Date.parse(a.available_at))[0];form._restCreditFrom=prior?.available_at||null;form._plannedClock=true;renderLoadingRestSuggestion(form);}
function openOrder(draft={}){const selected=state.trucks.find(t=>t.id===Number(draft.truck_id));const clock={...clockDefaults,...draft.clock};const clockFields=[['Driven today (h)','drive_today',9],['Driven since last break (h)','drive_since_break',4.5],['Duty elapsed today (h)','duty_today',13],['Driven this week (h)','drive_week',56],['Driven previous week (h)','drive_previous_week',56],['Weekly rest due in (h)','weekly_rest_due_in',144]].map(([label,key,max])=>field(label,'clock_'+key,Number(clock[key]).toFixed(2),'number',`required min="0" max="${max}" step="0.01"`)).join('');
  showModal(draft.id?'Edit loading order':'New loading order',`<form id="order-form">${errorBox}<div id="rest-suggestion" role="status"></div><input name="id" type="hidden" value="${draft.id||''}">
  ${!state.trucks.length||!state.drivers.length||state.locations.length<1?notice('Add a driver, truck and locations in the directory before saving an order.',true):''}
  <div class="form-grid">${searchSelectField('Tractor registration','truck_id',state.trucks.filter(t=>t.active).map(t=>({id:t.id,label:t.plate,hint:t.operation})),draft.truck_id,{required:true,empty:'Choose a tractor'})}${selectField('Driver','driver_id',options(state.drivers.filter(d=>d.active),draft.driver_id||selected?.driver_id,d=>d.name+' · '+d.carrier))}${trailerPicker('Trailer for this order',draft.trailer_id!==undefined?draft.trailer_id:(draft.trailer!==undefined?undefined:selected?.trailer_id),draft.trailer??selected?.trailer??'')}${field('Loading appointment · dispatch time','pickup_at',localParts(draft.pickup_at)||selectedDay+'T08:00','datetime-local','required')}
  <div class="field"><label for="f-loading_id">Loading point · city & company</label><div class="inline-actions"><select name="loading_id" id="f-loading_id" required>${options(state.locations,draft.loading_id,placeLabel)}</select><button type="button" class="btn small" data-action="quick-location" data-slot="loading_id">＋ New</button></div><div data-order-geo="loading_id"></div></div>
  <div class="field"><label for="f-unloading_id">Unloading point · city & company</label><div class="inline-actions"><select name="unloading_id" id="f-unloading_id" required>${options(state.locations,draft.unloading_id,placeLabel)}</select><button type="button" class="btn small" data-action="quick-location" data-slot="unloading_id">＋ New</button></div><div data-order-geo="unloading_id"></div></div>
  ${field('Loading duration (h)','loading_hours',draft.loading_hours??1,'number','required min="0" max="6" step="0.25"')}${field('Unloading duration (h)','unloading_hours',draft.unloading_hours??1,'number','required min="0" max="6" step="0.25"')}
  <div class="span-2 section-title">Route & delivery estimate</div>${selectField('Route calculation','route_mode',`<option value="manual" ${draft.route_mode!=='here'?'selected':''}>Manual kilometres & driving time</option><option value="here" ${draft.route_mode==='here'?'selected':''} ${state.here_configured?'':'disabled'}>HERE truck route ${state.here_configured?'':'(API key required)'}</option>`)}<div class="field"><label>Delivery date & time</label><input value="Calculated from route + driver clock" disabled><small>Unloading will also appear on its own planning day.</small></div>
  ${field('Distance (km) · manual mode','distance_km',draft.distance_km??'','number','min="0" max="15000" step="0.1"','Road distance, not straight-line distance.')}${field('Driving time (h) · manual mode','driving_hours',draft.driving_hours??'','number','min="0" max="240" step="0.01"','Pure driving time. Breaks, rests and handling are added automatically.')}
  </div><details><summary>Driver clock at loading · hours already used</summary><p class="subtitle">Default zeros mean the driver starts fresh after qualifying rest. Enter actual hours or carry forward the previous planned order. Loading and unloading count as duty.</p><div class="form-grid">${clockFields}</div><button class="btn small" type="button" data-action="carry-clock">↻ Carry forward previous planning</button><p id="clock-message" class="subtitle"></p></details>
  <div class="field"><label for="f-notes">Dispatch notes / plain text</label><textarea id="f-notes" name="notes" maxlength="5000" placeholder="References, contact names, loading instructions…">${esc(draft.notes||'')}</textarea></div>
  <label class="checkbox"><input type="checkbox" name="clock_confirmed" required ${draft.clock_confirmed?'checked':''}><span>I verified the driver's clock and the truck's ability to reach this loading point. Unassigned gaps counted as rest are planning assumptions. The ETA is an estimate, not a compliance certificate.</span></label>
  <div id="order-preview"></div><div class="form-actions"><button type="button" class="btn" data-action="preview-order">Calculate ETA</button><button type="submit" class="btn primary">${draft.id?'Save changes':'Create loading order'}</button></div></form>`,'LOADING ORDER / SINGLE DRIVER');
  syncRouteMode();renderLoadingRestSuggestion($('#order-form'));ensureOrderCoordinates($('#order-form'),true).catch(error=>showError($('#order-form'),error));
}
function syncRouteMode(){const form=$('#order-form');if(!form)return;const manual=form.elements.route_mode.value==='manual';for(const name of ['distance_km','driving_hours']){form.elements[name].disabled=!manual;form.elements[name].required=manual;}}
function previewHtml(plan,route){return `<div class="preview-box"><h3>Estimated unloading · ${formatDate(plan.unloading_at)}</h3><div class="preview-grid"><div><span>Road distance</span><strong>${km(route.distance_km)}</strong></div><div><span>Driving</span><strong>${hours(route.driving_hours)}</strong></div><div><span>Breaks & rest</span><strong>${hours(plan.rest_hours)}</strong></div><div><span>Road arrival</span><strong>${formatDate(plan.arrival_at)}</strong></div><div><span>Available after unloading</span><strong>${formatDate(plan.available_at)}</strong></div><div><span>Total to availability</span><strong>${hours(plan.elapsed_hours)}</strong></div></div>${route.notices?.length?notice(route.notices.map(esc).join('<br>'),true):''}<details><summary>Driving, breaks & handling timeline</summary>${timelineHtml(plan)}</details><p>Planning estimate with conservative single-driver rests. Availability does not guarantee remaining driving hours.</p></div>`;}
function timelineHtml(plan){return `<div class="timeline">${plan.timeline.map(e=>`<div class="timeline-row"><span>${esc(e.kind)} · ${hours(e.minutes/60)}</span><span>${formatDate(e.start)} → ${formatDate(e.end)}</span></div>`).join('')}</div>`;}
function orderDetail(id){const o=state.orders.find(x=>x.id===Number(id));if(!o)return;showModal(o.number,`<div class="detail-summary"><div><span>Tractor / trailer</span><strong>${esc(o.plate)} / ${esc(o.trailer||'—')}</strong></div><div><span>Driver / carrier</span><strong>${esc(o.driver_name)}</strong><p>${esc(o.carrier)}</p></div><div><span>Operation / status</span>${badge(o.operation)} ${badge(o.status,'gray')}</div></div><div class="detail-grid"><div><h3>Loading point</h3><p>${esc(placeLabel(getLocation(o.loading_id)))}<br>${esc(getLocation(o.loading_id)?.address)}<br><strong>${formatDate(o.pickup_at)}</strong></p></div><div><h3>Unloading point</h3><p>${esc(placeLabel(getLocation(o.unloading_id)))}<br>${esc(getLocation(o.unloading_id)?.address)}<br><strong>Estimated ${formatDate(o.unloading_at)}</strong></p></div></div>${previewHtml(o.plan,o.route_details)}${o.notes?`<div class="detail-grid"><div><h3>Dispatch notes</h3><p>${esc(o.notes)}</p></div></div>`:''}<p class="print-note">All times: Europe/Madrid dispatch clock. Estimated times require driver and location confirmation.</p><div class="form-actions"><button class="btn" data-action="print-order">Print order</button>${o.status==='Planned'?`<button class="btn" data-action="edit-order" data-id="${o.id}">Edit</button><button class="btn" data-action="complete-order" data-id="${o.id}">Mark completed</button>`:''}${o.status!=='Cancelled'?`<button class="btn danger" data-action="cancel-order" data-id="${o.id}">Cancel order</button>`:''}</div>`,'LOADING INSTRUCTIONS / DISPATCH COPY');}
function renderMatches(result){recommendationResults=result.candidates;$('#match-results').innerHTML=(result.candidates.length?result.candidates.map((r,index)=>`<article class="result-card"><div class="result-head"><h3><span class="rank">${index+1}</span>${esc(r.plate)} · ${esc(r.driver_name)}</h3>${badge(r.feasible===true?'Estimated on time':r.feasible===false?'Cannot reach in time':'Needs verification',r.feasible===true?'':r.feasible===false?'gray':'amber')}</div><p>${esc(r.carrier)} · ${esc(r.operation)} · Trailer ${esc(r.trailer||'—')}<br>From <strong>${esc(placeLabel(r.origin))}</strong><br>Position based on ${esc(r.origin_source)} · Available ${formatDate(r.available_at)}</p><div class="result-meta"><div><span>${r.road_km!=null?'Truck-road distance':'Straight-line distance'}</span><strong>${r.road_km!=null?km(r.road_km):r.air_km!=null?km(r.air_km):'Same postal area'}</strong></div><div><span>Estimated arrival</span><strong>${r.arrival_at?formatDate(r.arrival_at):'Not verified'}</strong></div></div>${notice(esc(r.warning),r.feasible!==true)}<div class="actions"><button class="btn small ${r.feasible===false?'':'primary'}" data-action="use-candidate" data-index="${index}" ${r.feasible===false?'disabled':''}>Use this tractor →</button></div></article>`).join(''):empty('No rankable trucks found','Add truck locations, availability times and coordinates. Trucks already assigned at the requested time are excluded.'))+(result.excluded.length?`<div class="padded"><details><summary>${result.excluded.length} trucks excluded</summary>${result.excluded.map(e=>`<p class="subtitle"><strong>${esc(e.plate)}</strong> · ${esc(e.reason)}</p>`).join('')}</details></div>`:'');}

document.addEventListener('click',async event=>{const nav=event.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return;}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;const form=button.closest('form');try{
  if(action==='close'){$('#modal').close();return;}
  if(action==='refresh-upcoming'){await refresh();return;}
  if(action==='upcoming-open-day'){selectedDay=button.dataset.date;period=1;filters.plate=state.trucks.find(t=>t.id===Number(button.dataset.truck))?.plate||'';filters.loading='';filters.unloading='';filters.operation='';filters.status='';navigate('planner');return;}
  if(action.startsWith('go-')){navigate(action.slice(3));return;}
  if(action==='new-order'){openOrder();return;}
  const masterActions={'new-trailer':['trailers',null],'edit-trailer':['trailers',id],'new-driver':['drivers',null],'new-truck':['trucks',null],'new-location':['locations',null],'edit-driver':['drivers',id],'edit-truck':['trucks',id],'edit-location':['locations',id]};
  if(masterActions[action]){openMaster(...masterActions[action]);return;}
  if(action==='prev-day'||action==='next-day'){selectedDay=addDays(selectedDay,(action==='next-day'?1:-1));render();return;}
  if(action==='today'){selectedDay=dayOf(state.now);render();return;}
  if(action==='clear-filters'){for(const key of Object.keys(filters))filters[key]='';render();return;}
  if(action==='order-detail'){orderDetail(id);return;}
  if(action==='edit-order'){const o=state.orders.find(x=>x.id===Number(id));openOrder({...o,clock:o.clock_input,route_mode:o.route_source==='Manual'?'manual':'here'});return;}
  if(action==='print-order'){window.print();return;}
  if(action==='reload-order'){const o=state.orders.find(x=>x.id===Number(id));const ready=new Date(o.available_at)>new Date(state.now)?o.available_at:state.now;openOrder({truck_id:o.truck_id,driver_id:o.driver_id,trailer_id:o.trailer_id,trailer:o.trailer,loading_id:o.unloading_id,pickup_at:ready,notes:'Next load after '+o.number});await carryOrderClock($('#order-form'));return;}
  if(action==='quick-location'){openMaster('locations',null,{draft:orderData(form),slot:button.dataset.slot});return;}
  if(action==='search-order-location'){button.disabled=true;const slot=button.dataset.slot;await searchOrderLocation(form,slot,$('#order-query-'+slot,form).value.trim());return;}
  if(action==='confirm-order-location'){button.disabled=true;await confirmOrderLocation(form,button.dataset.slot,Number(button.dataset.index));return;}
  if(action==='preview-order'){if(!validateSearchSelections(form))return;if(renderLoadingRestSuggestion(form)){$('#rest-suggestion').scrollIntoView({block:'nearest'});return;}button.disabled=true;if(!form.elements.loading_id.value||!form.elements.unloading_id.value)throw new Error('Choose both loading and unloading points before calculating the route.');if(!await ensureOrderCoordinates(form,true)){form.querySelector('.order-geo-box')?.scrollIntoView({block:'nearest'});return;}const data=orderData(form);const response=await api('/api/preview',data);$('#order-preview').innerHTML=previewHtml(response.plan,response.route);return;}
  if(action==='carry-clock'){button.disabled=true;await carryOrderClock(form);return;}
  if(action==='apply-rest-suggestion'){const suggestion=loadingRestSuggestion(orderData(form),form._restCreditFrom);if(!suggestion)return;form.elements.pickup_at.value=localParts(suggestion.pickup_at);for(const [key,value] of Object.entries(suggestion.clock))form.elements['clock_'+key].value=Number(value).toFixed(2);form.elements.clock_confirmed.checked=false;$('#order-preview').innerHTML='';$('.form-error',form).textContent='';$('#rest-suggestion').innerHTML=notice(`Proposed loading moved to <strong>${formatDate(suggestion.pickup_at)}</strong>, after ${suggestion.rest_hours} hours of assumed uninterrupted rest. Review the appointment and confirm actual rest with the driver before saving.`);$('#clock-message').textContent='Daily driving and duty reset after assumed qualifying rest; calendar-week driving totals are preserved.';return;}
  if(action==='complete-order'||action==='cancel-order'){if(!window.confirm(action==='cancel-order'?'Cancel this loading order? It will stay in history.':'Mark this order completed? The planned times will remain in history.'))return;await api('/api/order-status',{id:Number(id),status:action==='cancel-order'?'Cancelled':'Completed'});$('#modal').close();await refresh();toast('Order updated.');return;}
  if(action==='match-location'){navigate('matches');$('#main').innerHTML=matchesView(id);return;}
  if(action==='use-candidate'){const candidate=recommendationResults[Number(button.dataset.index)],match=formObject($('#match-form'));openOrder({truck_id:candidate.truck_id,driver_id:candidate.driver_id,trailer:candidate.trailer,loading_id:match.location_id,pickup_at:match.pickup_at,clock:candidate.clock||clockDefaults,notes:`Proposed repositioning from ${placeLabel(candidate.origin)}. ${candidate.road_km!=null?km(candidate.road_km)+' truck-road distance. ':''}Confirm and arrange the empty leg separately.`});if(!candidate.clock)await carryOrderClock($('#order-form'));return;}
  if(action==='geocode'){button.disabled=true;const values=formObject(form);const query=[values.address,values.postal_code,values.city,values.country].filter(Boolean).join(', ');const response=await api('/api/geocode',{query});const container=$('#geocode-results');container._matches=response.matches;container.innerHTML=response.matches.length?'<p class="subtitle">Confirm the correct address:</p>'+response.matches.map((m,i)=>`<button type="button" class="geo-option" data-action="choose-geocode" data-index="${i}">${esc(m.label)}<br>${m.lat}, ${m.lon} · ${esc(m.result_type)}</button>`).join(''):notice('No address matches. Refine the address or enter verified coordinates.',true);return;}
  if(action==='choose-geocode'){const selected=$('#geocode-results')._matches[Number(button.dataset.index)];form.elements.lat.value=selected.lat;form.elements.lon.value=selected.lon;form.elements.geo_label.value=selected.label;$('#geocode-results').innerHTML=notice('Selected: '+esc(selected.label));return;}
}catch(error){showError(form||$('#modal-content'),error);}finally{button.disabled=false;}});

function fillClock(response){const form=$('#order-form');for(const [key,value] of Object.entries(response.clock))form.elements['clock_'+key].value=Number(value).toFixed(2);$('#clock-message').textContent=response.message;$('details',form).open=true;$('#order-preview').innerHTML='';form._restCreditFrom=null;form._plannedClock=false;renderLoadingRestSuggestion(form);}
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(!validateSearchSelections(form))return;const button=$('[type=submit]',form);if(button)button.disabled=true;const error=$('.form-error',form);if(error)error.textContent='';try{
  if(form.getAttribute('id')==='master-form'){const data=formObject(form);if(data.id)data.id=Number(data.id);const result=await api('/api/'+form.dataset.type,data);const returnTo=form._returnTo;$('#modal').close();await refresh();if(returnTo)openOrder({...returnTo.draft,[returnTo.slot]:result.id});toast('Saved successfully.');}
  if(form.getAttribute('id')==='order-form'){if(renderLoadingRestSuggestion(form)){$('#rest-suggestion').scrollIntoView({block:'nearest'});return;}if(!await ensureOrderCoordinates(form,true)){form.querySelector('.order-geo-box')?.scrollIntoView({block:'nearest'});return;}const result=await api('/api/orders',orderData(form));$('#modal').close();await refresh();orderDetail(result.id);toast('Loading order saved. Both movements are now in the daily planning.');}
  if(form.getAttribute('id')==='match-form'){const data=formObject(form);$('#match-results').innerHTML='<div class="loading">Checking planned positions and availability…</div>';renderMatches(await api('/api/recommend',data));}
}catch(error){showError(form,error);if(form.getAttribute('id')==='match-form')$('#match-results').innerHTML=empty('Search could not be completed','Correct the inputs or connection and try again.');}finally{if(button)button.disabled=false;}});
document.addEventListener('change',event=>{const input=event.target;
  if(input.id==='upcoming-week'){weekOffset=Number(input.value);if(weekOffset===2)weekCount=1;loadUpcoming();return;}
  if(input.id==='upcoming-count'){weekCount=Number(input.value);loadUpcoming();return;}
  if(input.id==='upcoming-truck'){upcomingTruck=input.value;render();return;}
  if(input.id==='upcoming-operation'){upcomingOperation=input.value;render();return;}
  if(input.id==='planning-date'&&input.value){selectedDay=input.value;render();}
  if(input.dataset.filter){filters[input.dataset.filter]=input.value;render();}
  if(input.name==='truck_id'&&input.closest('#order-form')){const truck=state.trucks.find(t=>t.id===Number(input.value));if(truck){const form=$('#order-form');form.elements.driver_id.value=truck.driver_id||'';setSearchSelectValue(form,'trailer_id',truck.trailer_id);}}
  if(input.name==='route_mode')syncRouteMode();
  if(['route_mode','loading_id','unloading_id'].includes(input.name)&&input.closest('#order-form')){const form=input.closest('#order-form');ensureOrderCoordinates(form,true).catch(error=>showError(form,error));}
  if(input.closest('#order-form')&&input.name!=='clock_confirmed'){const form=input.closest('#order-form');$('#order-preview').innerHTML='';if((input.name||'').startsWith('clock_')||input.name==='truck_id'){form._restCreditFrom=null;form._plannedClock=false;}if(['pickup_at','driver_id'].includes(input.name)&&form._plannedClock){carryOrderClock(form).catch(error=>showError(form,error));}else renderLoadingRestSuggestion(form);}
});
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.filter){clearTimeout(filterTimer);const key=input.dataset.filter,value=input.value,start=input.selectionStart;filterTimer=setTimeout(()=>{filters[key]=value;render();const replacement=document.querySelector('[data-filter='+key+']');if(!replacement)return;replacement.focus();if(replacement.setSelectionRange)replacement.setSelectionRange(start,start);},250);}if(input.id==='directory-search'){const query=input.value.toLowerCase();for(const card of document.querySelectorAll('.directory-card'))card.hidden=!card.textContent.toLowerCase().includes(query);}});
$('#close-modal').addEventListener('click',()=>$('#modal').close());
refresh().catch(error=>{$('#main').innerHTML=empty('Could not connect to the local server',esc(error.message));toast(error.message,true);});





